NIGHT_LOADED({"seed":1083,"generated_at":"2026-10-21T06:00:00Z","chain":[1,3,2,4,5],"frame":{"collector":"J.D.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.D.","note_final":"Goed opgeborgen. Morgen om negen. — J.D.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.D.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.D.","initials":"J.D.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.D.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":2,"drawers":[{"id":"1-1","type":"P2","difficulty":3.0002,"rank":0.0882,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"WEV000602","role":"target","render":{"description":"Man ziet huis in brand staan, en voelt dat de muren warm zijn, een voorteken dat het huis zal afbranden.","place":null,"prov":"Gr.","year":1962,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/42965","original":"2 Voorloop.\nOp een morgen ging ik naar het werk. \nDaar zag ik opeens het huis van Timp in brand staan.\nNu moet men daar zo snel mogelijk heen gaan.\nZijn de muren koud, dan komt er een dode in dat huis, zijn de muren warm, dan brandt het op.\nIk voelde dus, de muren waren warm.\nDadelijk ging ik naor de vrouw terug.\nIk zeg: \"Timp zien hoes brandt gauw op.\"\nHet heeft nog twee jaar geduurd, toen ging het.","lang":"Standaardnederlands; Gronings","front":"original"},"home":"1-1"},{"id":"c2","story_id":"WEV005903","role":"helper","render":{"description":"Bij afbranden van zijn boerderij vertelt man dat hij lang van tevoren heeft gezien dat het huis in brand staat, maar er over heeft gezwegen.","place":"Wessingtange","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43264","original":"Veurloop.\nJoarn leden is hier brand west. Ik huilp de boer mit alles. De man stön aal man stil te kiekn en zee:“Nôn brand e ja.”\nIk vruig:“Hou komst door bie, wat betaikent dat?”\n“t Is wol al tien joar leden”, zee e dou, “op n oavend kwam k bie hoes en dou stôn alles in lichtelaaie. k Heb dr nooit over proot, mit ganaine, man nôn brand e ja.”","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9175,7.14444]},{"id":"c3","story_id":"WEV007406","role":"helper","render":{"description":"Lichten worden gezien als voorloop van brand.","place":"Musselkanaal","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44126","original":"Lichten zaggen ze vrouger voak. \"dr brandt weer wat\", zeden ze, zel wel weer gauw n huus aan goan. Dat geleuf was algemain.","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9325,7.01528]},{"id":"c4","story_id":"WEV013008","role":"helper","render":{"description":"Voorspelling dat alle witte huizen afbranden komt uit, alleen witte kerk staat er nog.","place":"Bourtange","prov":"Gr.","year":1966,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44092","original":"Oal vrouw K. zag vrouger ale widde huuzn in Boertange brannen.\n“Zai brant aal op”, zee ze. En t oal hef nog gliek kreegn ook. Allaind de widde kerke stait dr nog.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.01,7.19028]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Wessingtange.","Zoek Jipsingboertange op de kaart."],"lock":{"kind":"place","target_geo":[52.965,7.10139],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Jipsingboertange"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.1418,"rank":0.2835,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ070902","role":"member","render":{"description":"Mensen zagen eens een boerderij in brand staan. Maar toen ze dichterbij kwamen, was er niets aan de hand. Later is de boerderij echt afgebrand.","place":"Augustinusga","prov":"Fr.","year":1969,"code":"SINSAG 0491","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/27979","original":"Myn wiif fortelde wolris dat to Sybrandahûs - tusken Dokkum en Rinsumageast - seagen lju yn 'e nacht in boereplaets yn 'e brân. Hja hearden allerhande lûden en stemmen fan minsken. Sy gongen der hinne, mar der wie neat.\nLetter is dy plaets troch de tonger opbrând.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c2","story_id":"CJ088406","role":"member","render":{"description":"Een man zag eens een boerderij in brand staan, maar toen hij dichterbij kwam, bleek er niets aan de hand te zijn. Later is het bedrijf toch nog afgebrand.","place":"Harkema","prov":"Fr.","year":1971,"code":"SINSAG 0491","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33288","original":"yn 'e brân. 't Wie by de earste bocht as men gyng fan 'e brêge fan 'e Harkema nei Surhústerfean. Mar doe't omke der by kom, brânde 't net.\nLetter is dat spul ôfbrând.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c3","story_id":"KEMP295","role":"intruder","render":{"description":"Een jongen wordt van het weerwolven verlost, doordat zijn pels verbrand raakt. Zijn vrienden hebben hem hierbij onbedoeld geholpen.","place":"Broek","prov":"L.","year":1925,"code":"SINSAG 0824","initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/43420","original":"De weerwolf verlost\n\nTe Blitterswijk woonde een jonge man die de naam had des nachts uit weerwolven te gaan. Enige vrienden wilden echter wel eens bij die gedaanteverwiseling tegenwoordig zijn. Zij gingen daarom een avond naar zijn huis en zetten zich om de haard. Het ging op middernacht aan en daar niemand sprak van naar huis gaan, zweette de weerwolf water en bloed van benauwdheid. Hij wilde de deur uit, maar zijn kameraden beletten hem dit en hielden hem stevig vast.\nToen het middernacht sloeg, viel opeens een groot wolfsvel uit de schoorsteen in het vuur. De weerwolf begon te schreeuwen als een bezetene en stelde zich aan als een duivel. …","lang":"Standaardnederlands","front":"original"},"home":"cab:3"},{"id":"c4","story_id":"CJ037801","role":"member","render":{"description":"Een jongen en een meisje zagen vanuit de verte eens een brand, maar toen ze dichterbij kwamen, was er helemaal geen brand. Een jaar later is er op die plek toch brand uit gebroken.","place":"Kollum","prov":"Fr.","year":1968,"code":"SINSAG 0491","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/23086","original":"It is jierren lyn. Ik en myn feint kommen us fan Sweagerfean. Wy moesten nei de Triemen ta. Wy roannen de Úlke-loane del by Swagerfean. Doe't wy sahwat midden op 'e loane wienen, en oer de feart seagen, seinen wy: \"Sjoch, dêr is brân!\"\nDêr woenen wy hinne en sa kommen wy op 'e Trekwei. Mar dêr wie neat to sjen. Alles wie tsjuster.\nIn jier nei dy tiid briek dêr brân út op in pleats, krekt op datselde plak, dêr't wy de brân sjoen hienen.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Broek hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":3},"on_success":{"trail_note":0,"unlock_cabinet":3,"stack":["c1","c2","c4"]}},{"id":"1-3","type":"R1","difficulty":1.1089,"rank":0.159,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"CJ011312","role":"omen","render":{"description":"Bij een vaart hoorde men eens getimmer, maar er was niets te zien. Twee jaar later werd er een houten huis neergezet.","place":"Boornbergum","prov":"Fr.","year":1966,"code":"SINSAG 0487","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17751","original":"It wie yn 1888 en 't gebeurde op it Blaufallaet. Doe wie dêr noch net it greate kanael, mar noch in gewoane feart. Myn mem wenne dêr. Sy is greatbrocht woarn by in âldomke fan my op it Blaufallaet. \nSy wie sawntsjin jier, doe stie se mei har omke op in joun bûtendoar. Oan 'e oare kant de feart gong it drok op in klunderjen. Mar der wie neat to sjen. \nMem sei: \"Dêr sil op in duer wol in hûs komme.\" Twa jier letter, yn 1890, woarde dêr in houten hûs delset. Greate Marten (Kalsbeek) kom der yn to wenjen.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CJ021110","role":"omen","render":{"description":"Twee mannen die met de helm waren geboren, zagen nu en dan lijkstoeten.","place":"Haulerwijk","prov":"Fr.","year":1967,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20714","original":"Hjir wienen twa, dy't mei de helm geboaren wienen: Graanstra en âlde Merk. Sy seagen nou en dan lykstaesjes.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c3","story_id":"CJ036404","role":"omen","render":{"description":"Een waarzegster doet aan twee mannen voorspellingen over hun toekomstig werk en huis en maant hen voorzichtig te zijn met losse houtjes op de weg om ongelukken te voorkomen. Haar voorspellingen komen precies uit.","place":"Boornbergum","prov":"Fr.","year":1968,"code":"SINSAG 0489","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/22875","original":"Ik wie mei Bareld de Meer nei Snits ta to monsterjen. Mei de strikel yn 'e binnenbûse, om to ûngetiidzjen. Mar wy krigen beide gjin wurk. Bareld sei: \"Sille wy even nei Lytse Kjille ta op 'e Gerdyk? Dat wie in wiersizter.\nWy der hinne.\nKjille sei tsjin my: \"Binne jo troud?\"\n\"Ja\", sei 'k.\n\"Krij dan mar safolle kaerten\", sei se. Hja hie de kaerten út it laed helle fan 'e tafel. Hja gong by in stove op, sa kom se op 'e stoel. Sa lyts wie se.\n\"Om wurk út west?\" sei se. \"Ungetiidzje?\"\n\"Ja.\"\n\"En gjin wurk krige?\"\n\"Né\", sei 'k.\n\"Mar jo hà wurk\", sei se. \"Dêr geane jo moarn of oaremoarn hinne. Dêr fortsjinje jo fiifentwintich of seisentwintich goune. Der komt ek in nije wei by jimmes. …","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","2 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":2},"on_success":{"chime":2,"digit":{"value":2,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":3,"drawers":[{"id":"2-1","type":"P4","difficulty":1.7114,"rank":0.7644,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"LYST282","role":"top","render":{"description":"Een boerenknecht heeft verkering met een boerenmeid. Omdat hij haar ervan verdenkt te kunnen toveren, wil hij het uitmaken.","place":"Ede","prov":"Gld.","year":1937,"code":"SINSAG 0310","initials":"L.C.S.","url":"https://www.verhalenbank.nl/items/show/13626","half":"top"},"home":"2-1"},{"id":"c2","story_id":"ZEEUW056","role":"distractor","render":{"description":"De man ziet dat de hond de duivel is, laat zich weer naar boven brengen, waarna hij wordt vervloekt. Hij komt ziek thuis, en blijft lang ziek. Zijn hele leven blijft hij arm.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c3","story_id":"LYST282","role":"bottom","render":{"description":"Het meisje vraagt hem echter de volgende avond naar de schaapskooi te komen. De knecht stemt in. Als hij bij de schaapskooi staat, vliegt er opeens een witte gedaante voorbij. Vlak daarna verschijnt de boerenmeid, die bij hoog en laag beweert dat zij de witte gedaante niet geweest is. De knecht gelooft haar niet.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c4","story_id":"TINNEV065","role":"distractor","render":{"description":"Het groepje begint te rennen. Als ze uitgerend zijn vertelt de eerste man dat hij een 'grijze juffer' had gezien.","half":"bottom","code":"SINSAG 0310F"},"home":"2-1"},{"id":"c5","story_id":"YPFOE088","role":"distractor","render":{"description":"Hij is dat op een gegeven ogenblik beu en wil zijn broer eens goed wakker maken. Daarbij raakt hij hem aan de slaap waarop deze sterft. De familie verhuist omdat ze het niet langer kunnen bolwerken. De lindeboom is blijven bloeien. De vermoorde jongen spookt nog steeds in de buurt rond.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c6","story_id":"ZEEUW054","role":"distractor","render":{"description":"Daar waren 3 koffers met op een 'n hond, op de 2e 'n leeuw met de sleutel van de 3e in zijn bek, die de man moet pakken. Hij durft 't niet en de vrouw neemt afscheid voor 100 jaar.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c7","story_id":"CBOEK305","role":"distractor","render":{"description":"Als iemand haar rust verstoort, draait ze hem de nek om. Een sterke man gaat 's nachts naar het kasteel waar ze rondspookt en verdelgt haar voorgoed.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c8","story_id":"LAAN005","role":"distractor","render":{"description":"Er was een widde juvver, wiens kleed te lang was, waardoor iedereen erover viel. Een ziever heeft die afgeknipt en sindsdien ging het hem en zijn familie altijd goed.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c9","story_id":"ZEEUW053","role":"distractor","render":{"description":"De geest neemt hem mee door gangen, deuren en zalen, tot ze komen bij 5 kisten, waarop een grote zwarte hond zit, die hem de adem in de keel doet stokken. Hij is niet meer in staat te spreken en de geest neemt voor 100 jaar afscheid en de man staat weer op de weg, waar hij werd aangesproken, en sleept zich huiswaarts en is 2 dagen later dood. Iemand hoorde van zijn avontuur, ging het ook wagen, zag om middernacht een licht voor zich uit dansen, kreeg de schrik en vluchtte weg.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c10","story_id":"KEMP314","role":"distractor","render":{"description":"Het was lelijk met hem afgelopen als het een andere dag was geweest. De juffrouw geeft hem de mogelijkheid om haar geldkisten op te graven: die hij kan verdelen tussen hemzelf, de armen en de kerk. De volgende dinsdag gaat Drikus met zijn zwager Hannes de schat opgraven. Maar als Hannes zegt: 'kijk, daar zit de heks', zinken de kisten dieper dan ooit.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c11","story_id":"LYST030","role":"distractor","render":{"description":"Als tegenprestatie moet ze naakt door de kerk rennen. Ze doet dit met tegenzin. Later is er op de grond die ze heeft gekregen, een wit wief te zien. Men is ervan overtuigt dat de geest van de vrouw daar nog rondspookt.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c12","story_id":"CJ001413","role":"distractor","render":{"description":"Hij heeft zijn tante vermoord om haar geld en sinds die tijd spookt het er. Dit alles gebeurt dichtbij de plek waar het huis van sterke Hearke heeft gestaan.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c13","story_id":"CJ051004","role":"distractor","render":{"description":"Even plotseling als de vrouw en het paard verschenen zijn, verdwijnen ze weer. De man spoedt zich doodsbenauwd naar huis.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het onderste stuk noemt ‘knecht’ opnieuw.","Het nummer is SINSAG 0310. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c3"},"on_success":{"fuse":["c1","c3"],"stack":["c1","c3"]},"found_card":{"card":"c3"}},{"id":"2-2","type":"P3","difficulty":1.2226,"rank":0.7299,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CBOEK477","role":"member","render":{"description":"Een knecht moet in een weddenschap aantonen, dat hij de spit in de Witte Wieven-kuil durft te gooien. Hij gooit en daagt het witte wief uit, dat hem achtervolgt. Met paard en al springt de knecht over de onderdeur. Het witte wief gooit de spit, dat in de middelaar van de deur blijft zitten.","place":"Bathmen","prov":"Ov.","year":1892,"code":null,"initials":"J.V.","url":"https://www.verhalenbank.nl/items/show/39631","original":"In de buurtschap Loo, op het erve Noever ging men een weddenschap aan met een knecht, dat hij het spit niet durfde gooien in de Witte-wieven-kuul; deze bevond zich daar ergens in de buurt. Hij sprong te paard en joeg derwaarts, aldaar smeet hij het spit in de kuil met de woorden:\n\nWit wieven wit\nHier breng ik oe een spit\n(of: Wat heb ie'j op oe spit?)\n\nDaarop had het wit wief gezegd:\n\nA'j zoo lang wacht\nDak mien eene schoe toeknuppe\nEn de aander toerukke\nDan zal ie'j 't gebraad wezen.\n\nDe knecht rende toen in vliegenden vaart huiswaarts, achtervolgd door het wit wief en voor de achterdeur gekomen, was de bovendeur los en de onderdeur dicht, maar het paard was nogal vlug en sprong over de onderdeur. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c2","story_id":"LYST279","role":"member","render":{"description":"Een boerenknecht brengt het spit naar de Witte Wieve. Een van hen achtervolgt hem. De knecht kan net een huis binnenvluchten. De bijl die het Witte Wief gooide komt terecht in de stiepel. Het Witte Wief kon niet sneller lopen, omdat ze problemen had met een van haar schoenen.","place":"Tilligte","prov":"Ov.","year":1937,"code":null,"initials":"B.R.","url":"https://www.verhalenbank.nl/items/show/13623","original":"Door ouden wordt nog van de Wit Wieve verteld, die alleen kwaadaardig waren, wanneer ze getergd werden. Zo wordt verteld dat een boerenknecht eens het spit bracht naar de plaats, waar zij woonden. Hij werd door eene der witte wieve achtervolgd, doch hem niet kon inhalen, omdat ze in de haast maar een schoen had kunnen aantrekken. Toen de knecht het huis binnenvluchtte, wierp ze hem met een bijl achterna, die in de steil (deurpost) terecht kwam.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c3","story_id":"KEUNING005102","role":"intruder","render":{"description":"Witte spook dat nachts over een hek naar het land zweeft blijkt een schaap te zijn.","place":"Drachten","prov":"Fr.","year":1962,"code":null,"initials":"S.K.","url":"https://www.verhalenbank.nl/items/show/131150","original":"Sa ha se it yn Jistrum ek hast hâwn. Der laei njonken de hurde wei in brede mei gêrs bigroeide berm. En dêr kamen de stikken lân mei hikken op 'e daem op út. Nachts seach min hiel faek in wyt ding oer in hikke it lân yn sweven. Fansels, dat wie gjin goed spul. Fêst tsjoenderij. Mar hjir kaem ek ien, dy net oan sok spul leauwde en dy 't útmakke, dat it in drint (heideskiep) wie, dat fêst it gêrs yn de berm lekkerder foun as dat yn it lân.","lang":"Fries","front":"original","uncatalogued":true},"home":"cab:4"},{"id":"c4","story_id":"ENGELB_15_003","role":"member","render":{"description":"Over bestaan van witte wieven en spit in deurpost.","place":"Geesteren","prov":"Ov.","year":1979,"code":null,"initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128566","original":"H.E.: Van de witn wiew he’j doar wa mangs van heurd?\nVr.Vr.: Van de witn wiew is ok niks van woar.\nH.E.: Nee, mer te geet ok um t verhaal, he. Joa he’j hier nog zonnen beuld, zonnen witn wievnbeuld. Ne, nee, nee (door elkaar heen gepraat, ze zijn het met elkaar niet eens)\nVr. [Wolberink, Jan]: Wat hadn ze bie ouns ok zegd, oh jee no valt mie t kenneke in zee Dat stun nog moal vuur joarn in de Twentse kraant. Als ik t met ene schoen had vastgebondn, gevondn als de ander gebondn.\nA.Ve.: ... t spit nog in n stiel van n nienduur nog zitn.\nF.Ve.: t Spit brengn.","lang":"Twents","front":"original","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een spook.","De kaart over Drachten hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":4},"on_success":{"trail_note":2,"unlock_cabinet":4,"stack":["c1","c2","c4"]}},{"id":"2-3","type":"R2","difficulty":1.0967,"rank":0.8475,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"YPFOE070d","role":"card","render":{"description":"De verteller gaat met een paar vrienden op huis aan. Onderweg komen ze een wit meisje tegen dat zich snel voortbeweegt. Ze zweeft in de richting van een huisje. Ze gaan op onderzoek uit. Later heeft zich een oude man opgehangen, en men zegt dat het ermee in verband staat. De dominee staat erg sceptisch tegenover het verhaal.","place":"Goutum","prov":"Fr.","year":1972,"code":"SINSAG 0310","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12149","original":"Wite juffers\nWat ik hjir yn 'e Westerein sels sjoen ha. Dat is no lyn, ik tink sa'n fiif-, seis-, sânenfyftich jier. Myn kammeraat en ik gyngen de jûntiid om in oere of alve stadichoan nei hûs ta. Doe troffen wy in pear jongelju en dy hâlden ús oan. De man sei: 'Sjoch, wat is dêr? Dêr is in famke midden yn 'e sûkerei. By it hûs dêre is it allegearre út en tsjuster, mar hoe kin dan sa'n wyt famke der yn 't lân weze?' Doe seach ik it ek. Ik sei: 'Dan moatte wy dêr ris even sjen'. Mar dat famke avensrarde tige hurd en wy koenen sjen, dat it net gie, mar dat it sweefde. It hie de grutte sawat fan in gewoan famke, en sniewyt. Ik sei: 'No, sille wy ris sjen? …","lang":"Fries","front":"description"},"home":"2-3"},{"id":"c2","story_id":"CJ018012","role":"sill","render":{"description":"Op een spookplaats spoken altijd drie witte dames, zusters, rond. Later zou die plaats ook de 'Susterwei' heten.","place":"Garyp","prov":"Fr.","year":1967,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20251","stain":"drie"},"home":"2-3"},{"id":"c3","story_id":"LYST293","role":"card","render":{"description":"Een weg staat bekend als spookweg. 's Avonds en 's nachts is er op die weg een witte vrouw te zien met lang, zijachtig haar. Haar jurk is met veren bekleed. Dikwijls kan men 's morgens wat van die veertjes op de weg zien liggen. Haar aanwezigheid schijnt een noodlottige invloed te hebben.","place":"Holten","prov":"Ov.","year":1937,"code":"SINSAG 0310","initials":"G.J.W.","url":"https://www.verhalenbank.nl/items/show/13638","original":"Het Witte Wief van de Friezeberg\nDe weg van Rijssen naar Enter is vooral bekend als de spookweg. Vroeger liep langs de eerste helft van die weg door een rij dennen ongeveer 4 meter breed een voetpad dat door de meeste voetgangers gezocht werd om van de schaduw op de anders zoo stoffige zonnige weg te genieten. 's Avonds zou zich daar echter geen sterveling wagen, want dit pad was bij avond en nacht de geliefde wandelplaats van een witte vrouw, door meer dan één gezien. Ze was een slanke vrouw met lang zijachtig haar. Haar wit gewaad was met glanzende veeren bezet en menigmaal kon men 's morgens van die witte veertjes zien liggen. …","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c4","story_id":"YPFOE070b","role":"card","render":{"description":"Er was eens een man die met zijn hondekar van Hardegarijp naar Bergum ging. De hele weg heeft er een witte gestalte met hem meegereisd.","place":"Burgum","prov":"Fr.","year":1973,"code":"SINSAG 0310","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12147","original":"Wite juffers\nDer wie ris in man, dy reizge mei de hûnekarre de Simmerdyk del fan Hurdegaryp nei Burgum. It wie jûn en tige mistich. Hy siet yn 'e hûnekarre en njonken him siet in wite gestalte. De hiele tiid is dy njonken him meireizge, oan Burgum ta. Dy man hat in benaud oerke trochmakke.","lang":"Fries","front":"description"},"home":"2-3"},{"id":"c5","story_id":"LYST223","role":"card","render":{"description":"Grote Kees liep om middernacht over een bruggetje. Opeens kon hij zich niet meer bewegen. Witte Wieven zweven langs hem heen. Pas toen zij voorbij waren, kon hij zich weer verroeren.","place":"Putten","prov":"Gld.","year":1937,"code":null,"initials":"A.W.v.G.","url":"https://www.verhalenbank.nl/items/show/13487","original":"De \"Witte Wieven\" zijn hier in verhalen wel bekend. Van \"de groote Kees\" wordt verteld, dat hij ze gezien heeft. Toen hij een jonge kerel was, keerde hij eens tegen middernacht van een familiebezoek terug naar huis. Onderweg moest hij door een moerassige hei, de \"breistroet\", waar een bruggetje over een beek voerde. Midden op de brug gekomen, zag hij plotseling de witte wieven. Hij kon zich niet meer verroeren en drukte zich met de rug tegen de brugleuning. Langzaam zweefden ze nader en gingen rakelings langs hem heen over de brug. Na eenige tijd kon hij zich weer bewegen. Nat van 't zweet, \"an ieder haor hing 'n dropal\", kwam hij thuis. Ze zijn ook op de Staverense hei. Bovengenoemd persoon heeft het aldus aan een kennis van mij verteld.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c6","story_id":"ENGELB_01_005","role":"card","render":{"description":"Mannen die naar de plaats gaan waar vrouwen een wit wief hebben gezien, zien daar een wapperend wit laken.","place":"Gammelke","prov":"Ov.","year":1974,"code":"SINSAG 0310","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128373"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een G.","Garyp. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c2","object":"window","text":"Garyp"},"on_success":{"digit":{"value":3,"card":"c2","word":"drie","stained":"c2"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P1","difficulty":0.7182,"rank":0.5495,"note":"Alle vier noemen ze hetzelfde ding. Dat wordt het etiket. Niet ‘een beest’ schrijven.","cards":[{"id":"c1","story_id":"KUSTERS001702","role":"card","render":{"description":"Krans in bed als teken van aanstaand sterven kan niet uitelkaar worden gehaald. Boer verdenkt knecht van toverij, laat hem ergens anders werken en gooit krans in bakoven. Meteen staat de knecht bij de oven. Na verbranden van de krans is de knecht van de duivel bevrijd.","place":"Nederweert","prov":"L.","year":1962,"code":"SINSAG 0824","initials":"C.K.","url":"https://www.verhalenbank.nl/items/show/46365","original":"Bij 'n boer was 'n krans in 't bed als teken van nabije dood. Zo'n krans was zo fijn gevlochten, dat men ze niet uiteen kon krijgen. De boer verdacht zijn knecht van die hekserij en stuurde hem voor werk naar de Peel wel 2 uur ver. Daarop stookte de boer zijn bakoven en gooide de krans daarin. Meteen stond de knecht voor hem en men moest hem met geweld tegenhouden anders was hij 't vuur in gegaan. Toen de krans verbrand was, zuchtte de knecht verlicht: \"nu ben ik gelukkig\" Hij was van de duivel bevrijd.","lang":"Standaardnederlands","front":"original"},"home":"3-1"},{"id":"c2","story_id":"LINSSEN001002","role":"card","render":{"description":"Bij verbranden van kransen die knecht in boom heeft gehangen is weggestuurde knecht plotseling terug; bevrijding van betovering na verbranden van de kransen.","place":"Asenray","prov":"L.","year":1962,"code":"SINSAG 0824","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208255","original":"Kransen in bomen. Een boerenknecht hield er eigenaardige gewoonten op na. In een boom nabij de boerderij hing hij kransen op, althans men meende dat hij dat deed, aangezien hij vaak met aandacht daarnaar keek. Men vond dit zeer vreemd en men zocht een gelegenheid om die kransen te verwijderen. Men stuurde hem met paard en wagen naar Sittard. Toen hij enige uren weg was haalde men de kransen uit de bomen en wierp ze in de \"bakoven\", die destijds bij vele boerderijen stond en diende om het eigen brood te bakken. Op hetzelfde ogenblik dat de kransen begonnen te branden stond de knecht op mysterieuze wijze voor de bakoven en wilde de kransen naspringen. Hij werd hiervan weerhouden door anderen die de oven stookten. …","lang":"Standaardnederlands","front":"original"},"home":"3-1"},{"id":"c3","story_id":"LINSSEN002605","role":"card","render":{"description":"Knecht die om middernacht door velg in zwarte kat verandert, is verlost na verbranden van velg.","place":"Baexem","prov":"L.","year":1962,"code":"SINSAG 0824","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208342","original":"Volgens tweede verteller was er op Nelishof te Tungelroy een knecht die elke nacht tussen twaalf en een uur afwezig was. Door een raampje ging hij naar buiten. Hij klom dan op de schansenhoop en kwam er als kat af. De boer had hem bespied en gemerkt dat boven op de schansenhoop een velg lag van een karwiel. Die had de boer daar niet neergelegd en hij zocht verband tussen de spokerij (zwarte kat) en dat karwiel.\nDit zou hij vernietigen als de knecht afwezig was. Op zekere dag had hij hem met schapen naar Antwerpen gestuurd. Toen hij een dag weg was stak de boer zijn bakoven aan en wierp de velg erin.\nOp hetzelfde moment verscheen de knecht en wilde de oven in. Het gelukte slechts met drie man om hem daarvan te weerhouden. …","lang":"Standaardnederlands","front":"original"},"home":"3-1"},{"id":"c4","story_id":"LINSSEN003405","role":"card","render":{"description":"Knecht gaat 's nacht naar in boom verstopte riem; als riem in vuur wordt gegooid is knecht die ver weg moet zijn, aanwezig.","place":"Horn","prov":"L.","year":1962,"code":"SINSAG 0824","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208417","original":"V Een knecht van de Donk klaagde bij de boer dat zijn medeknecht er 's nachts vaak op uitging en zodoende zijn nachtrust stoorde. Men ging er eens op letten wat hij 's nachts uitvoerde. Men bespiedde hem. Op een nacht zag men dat hij naar Petite-Nak, een weiland, ging waar knotwilgen stonden. Bij een van deze knotwilgen bleef hij staan en reikte met zijn arm in de holle stam. De boer stuurde deze knecht op een morgen naar de Peel (Meyel) om turf. Intussen ging men naar de knotwilg en haalde daaruit een leren riem. De boer wilde die tijdens zijn afwezigheid verbranden, maar juist toen hij de riem in het vuur wilde gooien stond de knecht, die eigenlijk in Meyel moest zijn, in levenden lijve voor hem en wilde hem verhinderen de riem te verbranden.","lang":"Standaardnederlands","front":"original"},"home":"3-1"}],"hints":["Lees de vier nog eens. Let op wat er in elk van de vier vóórkomt, niet op wat erin gebeurt.","Het is een beroep.","Begint met een K. 6 letters."],"lock":{"kind":"word","salt":"fddfe1195edc1e48","accepted_hashes":["64ab63c278b93db0ff5ed8c9c09652ea3486b8651f87df36f8e96d83adcba05d","9e67d91addd644c5c179b64f354aafd38dc5af1f6b471341fb39be827409f6bd","9ea9d379e69452fcc1fb305d4e46b963e864e8a527afcd056f67f3ffab6f8899","a14da11948bf19ff6008e60615ad412586f29bae9f1c20ac00fbca37ba07a065","e005ff8d255ae74b7db39a2f638c815a626f55460d320fc4794e56b60275f2d1"]},"on_success":{"print_label":true,"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c4"}},{"id":"3-2","type":"P3","difficulty":1.0698,"rank":0.4838,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"KOOIJMAN0294","role":"intruder","render":{"description":"In het algemeen angst voor witte juffrouw.","place":"Ameide","prov":"Utr.","year":1962,"code":null,"initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/50995","original":"DE WITTE JUFFROUW\n\nBij 't Slot had je de witte juffrouw. Veel mensen waren d'r bang van. Maar m'n vader, dat was vroeger een stroper, ok van de armoei....werken van donker tot donker....en dan 's-avonds weer op stropen uit....maar die was niet bang van de witte juffrouw!","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"cab:2"},{"id":"c2","story_id":"CJ090105","role":"member","render":{"description":"Een van zeven broers is een weerwolf. Een van zeven zusters is een nachtmerrie. Een nachtmerrie komt door het sleutelgat het huis binnen.","place":"Twijzelerheide","prov":"Fr.","year":1971,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33428","original":"Fan sawn jonges is ien in wjerwolf.\nFan sawn famkes is ien in nachtmerje.\nIn nachtmerje komt troch 't kaeisgat yn 'e hûs.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c3","story_id":"CJ019728","role":"member","render":{"description":"Van zeven broers is er vaak één een weerwolf, meestal de oudste of de jongste. Zo'n weerwolf heeft de natuur van een wild dier.","place":"Sweagerbosk","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20528","original":"Fan 'e sawn bruorren is faek ien in wjerwolf. It is de âldste of de jongste. Hjir wie sa'n húshâlding. Dat wie Lammert Roek. De jongste, seinen se, wie in wjerwolf. Sa'n wjerwolf hie de natuer fan in wyld dier.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"CJ041909","role":"member","render":{"description":"De oudste of de jongste van zeven opeenvolgende dochters is een nachtmerrie. Bij zeven zonen is het een weerwolf.","place":"Twijzelerheide","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/23774","original":"Fan ien fan 'e sawn dochters, dy't op elkoar folgje, sûnder jonges der tusken is de âldste of de jongste in nachtmerje. Fan ien fan 'e sawn soannen is ien in wjerwolf.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Ameide hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":2},"on_success":{"trail_note":1,"unlock_cabinet":2,"stack":["c2","c3","c4"]}},{"id":"3-3","type":"R3","difficulty":1.0236,"rank":0.3077,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"CJ044011","role":"door","render":{"description":"Een van zeven zonen is een weerwolf. Men moet nooit ruzie krijgen met een weerwolf, want dan maakt hij je dood. \nEen meisje naaide altijd bij andere mensen. Haar vrijer vroeg haar eens om een zakdoek. Ze gaf het hem, en buiten verscheurde hij het ding helemaal. Daarna was hij weer normaal. Hij bleek een weerwolf te zijn. Toen heeft het meisje het uitgemaakt.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0823","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24049","original":"Ien fan sawn soannen wie in wjerwolf. As in wjerwolf jin kriget, makket er jin dea, seinen se froeger tsjin ús. Men mat der noait rûzje mei krije, sei in muoike yn 'e Westerein, dan pakke se jo.\nMyn wiif hat in kammeraetske hawn, dy naeide altyd by oare minsken. Dy hie forkearing mei in feint.\nOp in kear wie er by har, doe frege er har om har bûsdoek. Hja hie him de bûsdoek jown, mar doe hied er dy bûsdoek yn alle moster forskuord bûtendoar.\nLetter wie er wer goed west, mar 't is wol útrekke tusken dy beiden. Hwant hy wie in wjerwolf.\nHja hat it sels oan myn wiif forteld. Dat kammeraetske wenne oan it Wyldpaed.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c2","story_id":"HOL001024","role":"card","render":{"description":"Mensen die weerwolven niet aanraken; man die aan het weerwolven is, is op twee plaatsen tegelijk; weerwolven hebben vel om.","place":"Opheusden","prov":"Gld.","year":1962,"code":null,"initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/209732","original":"Gaart en Stoffel van Brenk konden weerwolven. Als deze en ook andere personen daarmee bezig waren, moest men ze niet “omlegge” op het bed, want dan ging het mis met hen. Mensen zagen \"Stomp\" onder de noteboom liggen, maar ook lag hij thuis op bed. Hij was toen aan het weerwolven. Weerwolven hadden een vel om.","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c3","story_id":"VVUNL049","role":"card","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":"SINSAG 0824","initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c4","story_id":"KOOIJMAN1182","role":"card","render":{"description":"Er woonde vroeger in Blokland een vrouw en die beweerde dat ze iedere avond de weerwolf buiten tekeer hoorde gaan tussen half elf en twaalf uur.","place":"Blokland","prov":"Utr.","year":1963,"code":"SINSAG 0804","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/72678","original":"De weerwolf, de weerwolf. Nou je 't zegt. D'r woonde vroeger in Blokland een vrouw. Die woonde daar op d'r eige alleen. En die vrouw die beweerde, ze hoorde iedere avond de weerwolf buite tekeergaan. Iedere avond tusse half elf en twaalf uur. Ze sloot alles d'r voor af.","lang":"Utrechts","front":"description"},"home":"3-3"},{"id":"c5","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c1","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c2"},"stack":["c2","c3","c4","c5"]}}]},{"id":4,"label":"Spoken","digit":4,"drawers":[{"id":"4-1","type":"P5","difficulty":0.7262,"rank":0.625,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"CJ028904","role":"variant","render":{"description":"Twee boeren willen vroeg in de ochtend de koeien gaan melken, als een van hen een gestalte aan de andere kant van de sloot ziet lopen. De groet van de boer wordt niet beantwoord: het is een spookverschijning die even plotseling als hij verschenen is, weer verdwijnt.","place":"Augustinusga","prov":"Fr.","year":1967,"code":"SINSAG 0475","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21852","original":"Hjir yn Stiensgea wennen twa âlde feinten, dat wienen Albert en Ate. Dy wienen boer. Sy dienen alles togearre. Se hienen lân yn Surhuzum.\nAlle moarnen gongen se mei in jok mei amers op 'e nekke to melken. Sy gongen de reed by de skoalle del.\nOp in kear, doe wienen se noch mar in lyts eintsje fuort, doe seach Ate dat der ien flakby op 'e oare kant fan 'e sleat mei harren opstapte. Ate sei: \"Goeije morgen.\" Mar dy oare sei neat werom. Albert sei tsjin Ate: \"Hwat biseistû: goeije morgen.\" \"Seachstû dan neat?\" sei Ate.\nAlbert hie neat sjoen en de gestalte wie wer fuort.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c2","story_id":"CJ046305","role":"variant","render":{"description":"Een man ziet 's nachts een oud mensje naderen. Als hij het vrouwtje groet, groet ze niet terug. Als de man haar nakijkt, is ze plotseling verdwenen. Het is een spookvrouw.","place":"Surhuisterveen","prov":"Fr.","year":1968,"code":"SINSAG 0475","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24417","original":"'t Wie feest by Bouke Pultrum yn 'e Houtigehage. (dat wie de kastlein). Myn styfheit moest de moarns ier en bitiid it hynder fan syn broer út it lân wei helje.\nDoe seach er in âld-minske oankommen.\n\"Ik tocht,\" sei er, \"hwat is dy hjir bitiid. Ik sei: - Goeije morgen, - mar hja sei neat werom. Ik sei noch us - Goeije morgen - , mar sy sei wer neat.\nDoe't se my foarby wie seach ik skruten achterom. Sy woarde samar wei yn 'e Brantsdobbe en ik haw har noait wer sjoen.\"\nSûnt dy tiid is er bang woarn. Hy doarst letter noait wer allinne yn syn eigen wein to sliepen. Hy moest altyd ien by him ha.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c3","story_id":"CJ101901","role":"variant","render":{"description":"Tsjerk vertelde altijd over spokerij. Op een avond moest hij door een hek. Daar zag hij een oud vrouwtje. Hij vroeg wie er het eerst ging: hij of zij. Op dat moment verdween het mensje alsof het er nooit was geweest. Het was een spookverschijning.","place":"Augustinusga","prov":"Fr.","year":1973,"code":"SINSAG 0475","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37086","original":"Tsjerk Kooistra kaem wolris by ús âlden to jounpraten, en dan hied er it in bulte oer spoekjen.\nHy fortelde op in kear, hy soe ris op in joun to praten. Hy moast troch in hekke hinne. Doe stie dêr in âld minske by dy hekke. Hy seach fuort wol dat it net doogde, mar hy sei tsjin har: \"Hwa mat der earst troch: ik of jo?\"\nMei't er dat sein hie wie se fertrokken, as wie se weifage.\nTsjerk hie har net wer sjoen. 't Hie in forskining west. Dit gebeurde yn Surhuzum.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Friesland werd een tijdstip genoemd: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.D.","summary":true},"home":"4-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1967.","Op die kaart staat een tijdstip. Welk?"],"lock":{"kind":"word","salt":"fddfe1195edc1e48","accepted_hashes":["6573b4e0aa7df501abe3afd948376a30680e139f13170d6866f610ca98da8b84","b4ea4f2357ea38cbd0310ac87cc1c3d8f1782b9fba9c656dfdcdccf03a42c094","da8ea4d2a554d89f399e6d6d22de23700c93bbefe181ae25b43ab10ed66c0d16"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.567,"rank":1.3,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ053402","role":"member","render":{"description":"Het komt wel eens voor dat een dode geen rust kan vinden omdat een aan hem gedane belofte niet nagekomen is. Als de dominee de dode aanspreekt op zijn onvervulde wens en die wens wordt alsnog vervult, vindt de dode rust. Als de dode nog iets overhandigd moet worden, moet je dat in een zakdoek bij elkaar rollen en de punt van de zakdoek vasthouden. Als je dit niet op die manier doet, schroeit je vel eraf.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25362","original":"It gebeurt soms wol us, dat ien dy't to hôf brocht is de rêst net fynt. Dan komt er wer. Meastal mat er dan hwat ha. De doomny freget him dan wol faek hwer't er forlet fan hat. Dan neamt er dat.\nAs men him dat jowt komt er net wer.\nMar men mat goed oppasse hoe't men it him jowt. Men mat it yn in bûsdoek byelkoar rolje en in tippe fan 'e bûsdoek fêsthâlde. Sa mat men it him jaen. Oars skroeit it fel der ôf. De bûsdoek skroeit nou.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c2","story_id":"BIJLSMA006903","role":"intruder","render":{"description":"'s Nachts wordt dominee omringd door donkere gedaanten die verdwijnen als hij zegt dat als ze van de duivel zijn weg moeten gaan en als ze van God zijn naar hem toe moeten komen.","place":"Wijckel","prov":"Fr.","year":1966,"code":null,"initials":"T.B.","url":"https://www.verhalenbank.nl/items/show/130636","original":"Op in nacht roun to Kipenburch allinne in dûmny op 'e wei. Hy sei: \"Zo alleen op de weg is toch vervelend\". Mar tagelyk seach er ek hwat oankommen. Hy wie by de Skearslipersbrêge, doe't der dûnkere gedaenten om him hinne strúnden. Dûmny sei: \"Als gij van de duivel komt, wijk van mij; komt ge van God, komt tot mij\". Doe wienen de gedaenten samar fordwoun.","lang":"Fries","front":"original","uncatalogued":true},"home":"cab:5"},{"id":"c3","story_id":"CJ111728","role":"member","render":{"description":"Als overledenen na hun dood blijven ronddolen, kunnen ze geen rust vinden omdat ze iets uitgehaald hebben of omdat een belofte aan hen gedaan niet nagekomen is. Ook de zielen van vermoorde mensen dolen 's nachts rond. Een man die zijn vrouw bij haar leven slecht behandelde, wordt na de dood van zijn vrouw voortdurend lastiggevallen door haar geest.","place":"Kollumersweach","prov":"Fr.","year":1974,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/29939","original":"Soms dwaelden der minsken op 'e paden om dy't al stoarn wienen. Dy hienen hwat útheefd en koenen de rêst net fine. Of se hienen noch in bigearte, dy't earst yn forfulling gean moest.\nEk guon dy't formoarde wienen dwelmen nachts om. Yn Kollumersweach wie in wiif stoarn, dy har man hie har min bihandele. Nei har dea kaem se hyltyd wer by dy man. Soms roun se njonken him lâns. Hy koe har net wer kwyt wurde.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c4","story_id":"CJ002908","role":"member","render":{"description":"Een vrouw sterft in Egypte en ze bezoekt dagelijks haar man. De man haalt de dominee erbij en de vrouw zegt tegen de dominee wat ze begeert. De man doet wat de vrouw wil en sindsien spookt het er niet meer.","place":"Kollumersweach","prov":"Fr.","year":1950,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/15731","original":"Yn Egypte wenne in man, dy syn wyfke forstoar, mar nei har dea kom se alle dagen by him. Hy helle de dûmny der by, dy't har oanspruts en frege hwat se bigearde. Oan dy dûmny joech se har bigearte to witen. De man foldie oan dy bigearte en it spoekjen wie dien.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Wijckel hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c1","c3","c4"]}},{"id":"4-3","type":"R4","difficulty":1.2229,"rank":0.875,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"CJ062011","role":"top","render":{"description":"Iemand woont in Harkema en als hij 's laat van de boer komt, ontmoet hij altijd een oud vrouwtje op het pad die hij gedag zegt.","place":"Harkema","prov":"Fr.","year":1969,"code":"SINSAG 0450","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/26947","half":"top"},"home":"4-3"},{"id":"c2","story_id":"KEMP263","role":"half","render":{"description":"Die zegt dat het broertje aan de geest moet vragen wat er aan de hand is. En het antwoord luidt dat de jongen vijfentwintig jaar te vroeg gestorven is door de steekpartij. Zijn ziel moet al die jaren rond blijven spoken tot de tijd om is. De pastoor gebiedt om de geest in een aparte kamer op te sluiten die de komende vijfentwintig jaar niet meer geopend mag worden.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"},{"id":"c3","story_id":"CJ109412","role":"half","render":{"description":"De dominee slaat de bijbel open en legt een sleutel van het huis op een zekere tekst. De volgende ochtend is de sleutel gedraaid in de richting van de appelboom. Daar blijkt een vermoord kind te zijn begraven. Nadat het kind is herbegraven op het kerkhof is het spoken opgehouden.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"},{"id":"c4","story_id":"CJ030711","role":"half","render":{"description":"Een van de familieleden krijgt eens uit het niets een hand toegestoken. Ook de schuurdeuren waaien vanzelf open.","half":"bottom","code":"SINSAG 0478"},"home":"4-3"},{"id":"c5","story_id":"KEMP181","role":"half","render":{"description":"De lichaamsdelen komen samen en vormen zich tot een oude man. Een spook, dat de soldaat steeds bevelen geeft: dat hij naar de kelder moet en een steen optillen etc. De man weigert dit brutaal en laat het spook alles zelf doen. In de hofstee blijken drie potten goud verborgen te zijn. Van de geest moet de soldaat een pot schenken aan de kerk, een aan de armen en een mag hij zelf houden, als dank voor het verlossen van het spook, dat in zijn leven slecht was geweest en armen uitbuitte.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c6","story_id":"BLECOURTNB0111","role":"half","render":{"description":"Gevraagd naar de reden van de verschijning van de schim, antwoordt deze dat hij haar vader is en pas in de hemel kan komen als er nog drie missen zijn gelezen. Nadat het meisje hieraan heeft voldaan verbetert haar gezondheid.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c7","story_id":"CJ062011","role":"bottom","render":{"description":"Ze veegt altijd het paadje en het erf met een bezem. Op een avond met volle maan ziet hij het vrouwtje steunend op de bezem weer op het erf staan, hoewel ze al vier maanden dood is.","half":"bottom","code":"SINSAG 0450","stain":"vier"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘vrouw’ opnieuw.","Het nummer is SINSAG 0450. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c7","object":"typewriter"},"on_success":{"fuse":["c1","c7"],"type_line":"Verteller: de vorige assistent.","digit":{"value":4,"card":"c1","word":"vier","stained":"c7"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
